  (uuid_generate_v4(), 'vintage-sterling-silver-eagle-earrings-by-manygoats', '1487404056', 'https://www.etsy.com/listing/1487404056/vintage-sterling-silver-eagle-earrings?click_key=5c75ed83-faac-4cf9-9683-2746579226dc%3ALT7cfb98e68fce448280598781a19e752bc5b3d9e8&click_sum=587fe03f&ls=s&ga_order=most_relevant&ga_search_type=all&ga_view_type=gallery&ga_search_query=Navajo+jewelry&ref=search_grid-89344-10-31&sr_prefetch=1&pf_from=search&frs=1&cns=1&sts=1&content_source=5c75ed83-faac-4cf9-9683-2746579226dc%253ALT7cfb98e68fce448280598781a19e752bc5b3d9e8',
